def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping/touching intervals in b
    b_merged = []
    for start, end in b_intervals:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1] = [b_merged[-1][0], max(b_merged[-1][1], end)]
        else:
            b_merged.append([start, end])

    result = []

    for a_start, a_end in a_intervals:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_intervals = []
            for curr_start, curr_end in current_intervals:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap - keep the parts that don't overlap
                    if curr_start < b_start:
                        new_intervals.append([curr_start, b_start])
                    if curr_end > b_end:
                        new_intervals.append([b_end, curr_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge adjacent/overlapping intervals in result
    if not result:
        return []

    result.sort()
    merged = [result[0]]
    for start, end in result[1:]:
        if start <= merged[-1][1]:
            merged[-1] = [merged[-1][0], max(merged[-1][1], end)]
        else:
            merged.append([start, end])

    return merged

